export function msg(id:string,ts:number,from:string,subject:string,body:string,filename='') { return {id,threadId:'t1',labelIds:['INBOX'],internalDate:ts,payload:{mimeType:'multipart/mixed',headers:[{name:'From',value:from},{name:'To',value:'me@example.com'},{name:'Subject',value:subject}],parts:[{mimeType:'text/plain',filename:'',body:{data:Buffer.from(body).toString('base64url')}},...(filename?[{mimeType:'application/pdf',filename,body:{attachmentId:'a1',size:123}}]:[])]}}; }
